hooks_dir = os.path.join(project, 'apps/web/src/hooks')
for f in sorted(os.listdir(hooks_dir)):
    if not f.endswith(('.js', '.jsx')):
        continue
    path = os.path.join(hooks_dir, f)
    with open(path) as fh:
        content = fh.read()
        lines = content.count('\n')

    # Count: useState, useEffect, useCallback, useRef
    states = len(re.findall(r'useState', content))
    effects = len(re.findall(r'useEffect', content))
    callbacks = len(re.findall(r'useCallback', content))
    refs = len(re.findall(r'useRef', content))
    exports = len(re.findall(r'export\s+(?:default\s+)?function', content))

    complexity = states + effects * 2 + callbacks
    risk = "HIGH" if complexity > 20 or lines > 300 else "MED" if complexity > 10 or lines > 150 else "LOW"

    print(f"  {f:30s} {lines:4d}L  useState={states} effect={effects} ref={refs}  [{risk}]")

# 2. Duplicate patterns in hooks
print("\n[2] Hooks 间重复模式")
patterns = defaultdict(list)
for f in os.listdir(hooks_dir):
    if not f.endswith(('.js', '.jsx')):
        continue
    path = os.path.join(hooks_dir, f)
    with open(path) as fh:
        content = fh.read()

    # Check for common duplicated patterns
    if 'WebSocket' in content: patterns['WebSocket 管理'].append(f)
    if 'sessionKeyRef' in content or 'encrypt' in content: patterns['加密层'].append(f)
    if 'step ===' in content or "setStep(" in content: patterns['状态机(step)'].append(f)
    if 'pcRef' in content or 'createOffer' in content: patterns['WebRTC PC'].append(f)
    if 'cleanup' in content.lower() or 'close()' in content: patterns['资源清理'].append(f)
    if 'roomId' in content: patterns['房间管理'].append(f)

for pattern, files in sorted(patterns.items(), key=lambda x: -len(x[1])):
    if len(files) > 1:
        print(f"  {pattern}: {', '.join(sorted(files))}")

# 3. Error handling gaps in hooks
print("\n[3] Hooks 错误处理缺口")
for f in os.listdir(hooks_dir):
    if not f.endswith(('.js', '.jsx')):
        continue
    path = os.path.join(hooks_dir, f)
    with open(path) as fh:
        lines = fh.readlines()

    issues = []
    for i, line in enumerate(lines, 1):
        s = line.strip()
        if '.then(' in s and '.catch(' not in s:
            nxt = ''.join(lines[i:i+3])
            if '.catch(' not in nxt:
                issues.append(f"L{i}: .then() 无 catch")
        if s.startswith('await ') and 'try' not in ''.join(lines[max(0,i-5):i]):
            issues.append(f"L{i}: await 无 try/catch")

    if issues:
        print(f"  {f}:")
        for iss in issues[:5]:
            print(f"    {iss}")

# 4. Large functions
print("\n[4] 大函数检测 (>50行)")
for root, dirs, files in os.walk(os.path.join(project, 'apps/web/src')):
    dirs[:] = [d for d in dirs if d not in ('node_modules',)]
    for f in files:
        if not f.endswith(('.js', '.jsx')):
            continue
        path = os.path.join(root, f)
        rel = os.path.relpath(path, project)
        with open(path) as fh:
            lines = fh.readlines()

        # Simple heuristic: find function definitions and measure until next function or end
        func_start = None
        func_name = None
        for i, line in enumerate(lines):
            m = re.match(r'\s*(?:export\s+)?(?:default\s+)?function\s+(\w+)', line)
            m2 = re.match(r'\s*(?:export\s+)?(?:const|let)\s+(\w+)\s*=\s*(?:async\s+)?(?:\(|function)', line)
            if m or m2:
                if func_start and func_name:
                    size = i - func_start
                    if size > 50:
                        print(f"  {rel}:{func_name} — {size} 行")
                func_start = i
                func_name = (m or m2).group(1)
        # Check last function
        if func_start and func_name:
            size = len(lines) - func_start
            if size > 50:
                print(f"  {rel}:{func_name} — {size} 行")
"}

