import {
  buildShareUrl,
  extractOfferFromUrl,
  clearShareHash,
  buildRoomJoinUrl,
  extractRoomCodeFromUrl,
  extractRoomCodeFromPastedText,
} from './shareUrl.js'

// btoa is available in Node 16+
const BASE = 'http://localhost:5173'

describe('buildShareUrl / extractOfferFromUrl', () => {
  it('round-trips an offer code', () => {
    const offer = btoa('{"type":"offer","sdp":"v=0..."}')
    const url = buildShareUrl(offer, BASE)
    expect(url).toContain('#join=')
    const extracted = extractOfferFromUrl(url)
    expect(extracted).toBe(offer)
  })

  it('returns null for URL without hash', () => {
    expect(extractOfferFromUrl('http://example.com')).toBeNull()
  })
})

describe('buildRoomJoinUrl / extractRoomCodeFromUrl', () => {
  it('round-trips a room code', () => {
    const code = 'ABCD1234'
    const url = buildRoomJoinUrl(code, BASE)
    expect(url).toContain('#room=')
    const extracted = extractRoomCodeFromUrl(url)
    expect(extracted).toBe(code)
  })

  it('returns null for URL without room hash', () => {
    expect(extractRoomCodeFromUrl('http://example.com#join=xxx')).toBeNull()
  })
})

describe('extractRoomCodeFromPastedText', () => {
  it('extracts room code from full URL', () => {
    const result = extractRoomCodeFromPastedText('http://localhost:5173#room=ABCD1234')
    expect(result).toBe('ABCD1234')
  })

  it('extracts room code from bare code', () => {
    const result = extractRoomCodeFromPastedText('ABCD1234')
    expect(result).toBe('ABCD1234')
  })

  it('returns null for empty input', () => {
    expect(extractRoomCodeFromPastedText('')).toBeNull()
  })
})

describe('clearShareHash', () => {
  it('removes join hash from URL', () => {
    const url = 'http://localhost:5173#join=xxx'
    expect(clearShareHash(url)).toBe('http://localhost:5173')
  })
})
