{"content": "/**
 * usePlatformWS — WebSocket connection and message dispatch for platform.
 *
 * Manages:
 *  - Persistent WebSocket to signaling server
 *  - Auto-reconnect on disconnect
 *  - Message dispatch (queue, rooms, leaderboard, signaling, witness)
 *  - State: isOnline, onlineCount, queueState, rooms, leaderboard
 */
import { useState, useRef, useCallback, useEffect } from 'react'
import { parseWsMessage } from '../lib/platformConnUtils.js'
import { decodeAnswer } from '../lib/webrtc.js'

export function usePlatformWS({
  SIGNALING_URL,
  userRef,
  mountedRef,
  wsRef,
  reconnectTimer,
  // Callbacks
  onRegistered, onIdentified, onMatchFound, onSignal,
  onRoomCreated, onResultRecorded, onWitnessError,
  // P2P callbacks
  setupAsHost, handleGuestOffer,
  // Queue state (read-only from hook consumer)
  queueState, setQueueState, setQueueMode, setMatchInfo,
}) {
  const [isOnline, setIsOnline] = useState(false)
  const [onlineCount, setOnlineCount] = useState(0)
  const [rooms, setRooms] = useState([])
  const [roomsLoading, setRoomsLoading] = useState(false)
  const [leaderboard, setLeaderboard] = useState([])
  const [leaderboardLoading, setLeaderboardLoading] = useState(false)

  // Refs for P2P state (set by parent)
  const pcRef = useRef(null)
  const p2pRoleRef = useRef(null)
  const matchInfoRef = useRef(null)

  const wsSend = useCallback((obj) => {
    const ws = wsRef.current
    if (ws && ws.readyState === WebSocket.OPEN) {
      ws.send(JSON.stringify(obj))
    }
  }, [wsRef])

  const handleWsMessage = useCallback(async (raw) => {
    const msg = parseWsMessage(raw)
    if (!msg) return

    switch (msg.type) {
      case 'registered': {
        const u = {
          userId: msg.userId, token: msg.token, nickname: msg.nickname,
          elo: msg.elo ?? 1200, rank: msg.rank ?? null,
          wins: msg.wins ?? 0, losses: msg.losses ?? 0, draws: msg.draws ?? 0,
        }
        onRegistered?.(u)
        if (mountedRef.current) setIsOnline(true)
        break
      }
      case 'identified': {
        onIdentified?.(msg)
        if (mountedRef.current) setIsOnline(true)
        break
      }
      case 'online_count':
        if (mountedRef.current) setOnlineCount(msg.count)
        break
      case 'queue_info':
        if (mountedRef.current && !msg.inQueue && queueState === 'queuing') setQueueState('idle')
        break
      case 'queue_left':
        if (mountedRef.current) { setQueueState('idle'); setQueueMode(null) }
        break
      case 'match_found': {
        const mi = {
          roomCode: msg.roomCode, youAre: msg.youAre, mode: msg.mode,
          opponentNickname: msg.opponentNickname, opponentElo: msg.opponentElo,
        }
        matchInfoRef.current = mi
        if (mountedRef.current) { setMatchInfo(mi); setQueueState('matched') }
        if (msg.youAre === 'host') {
          try { await setupAsHost() } catch (e) { console.error('[platform] host P2P:', e) }
        }
        onMatchFound?.(mi)
        break
      }
      case 'signal': {
        if (msg.data?.type === 'offer' && p2pRoleRef.current === null) {
          p2pRoleRef.current = 'guest'
          try { await handleGuestOffer(msg.data.offer) } catch (e) { console.error('[platform] guest:', e) }
        } else if (msg.data?.type === 'answer' && p2pRoleRef.current === 'host' && pcRef.current) {
          try { await pcRef.current.setRemoteDescription(decodeAnswer(msg.data.answer)) }
          catch (e) { console.error('[platform] answer:', e) }
        }
        onSignal?.(msg.data)
        break
      }
      case 'rooms_list':
        if (mountedRef.current) { setRooms(msg.rooms ?? []); setRoomsLoading(false) }
        break
      case 'rooms_updated':
        if (mountedRef.current) setRooms(msg.rooms ?? [])
        break
      case 'room_created':
        if (mountedRef.current) onRoomCreated?.(msg)
        break
      case 'leaderboard':
        if (mountedRef.current) { setLeaderboard(msg.entries ?? []); setLeaderboardLoading(false) }
        break
      case 'result_recorded':
        onResultRecorded?.(msg)
        break
      case 'witness_error':
        if (mountedRef.current && msg.message) onWitnessError?.(msg)
        break
      case 'error':
        console.warn('[platform] server error:', msg.message)
        break
      default: break
    }
  }, [queueState, setupAsHost, handleGuestOffer, mountedRef, wsRef,
      onRegistered, onIdentified, onMatchFound, onSignal,
      onRoomCreated, onResultRecorded, onWitnessError,
      setQueueState, setQueueMode, setMatchInfo])

  const connect = useCallback(() => {
    if (!SIGNALING_URL) return
    if (wsRef.current && wsRef.current.readyState <= WebSocket.OPEN) return
    const ws = new WebSocket(SIGNALING_URL)
    wsRef.current = ws
    ws.onopen = () => {
      if (!mountedRef.current) return
      setIsOnline(true)
      const u = userRef.current
      if (u?.userId && u?.token) {
        ws.send(JSON.stringify({ type: 'identify', userId: u.userId, token: u.token }))
      }
    }
    ws.onmessage = ({ data }) => handleWsMessage(data)
    ws.onerror = () => {}
    ws.onclose = () => {
      if (!mountedRef.current) return
      setIsOnline(false)
      reconnectTimer.current = setTimeout(() => {
        if (mountedRef.current) connect()
      }, 3000)
    }
  }, [SIGNALING_URL, handleWsMessage, mountedRef, wsRef, userRef, reconnectTimer])

  const disconnect = useCallback(() => {
    clearTimeout(reconnectTimer.current)
    wsRef.current?.close()
    wsRef.current = null
    setIsOnline(false)
  }, [reconnectTimer, wsRef])

  return {
    isOnline, onlineCount, wsSend, connect, disconnect,
    rooms, roomsLoading, setRoomsLoading, refreshRooms: () => { setRoomsLoading(true); wsSend({ type: 'list_rooms' }) },
    leaderboard, leaderboardLoading, setLeaderboardLoading,
    fetchLeaderboard: () => { setLeaderboardLoading(true); wsSend({ type: 'get_leaderboard', limit: 20 }) },
    pcRef, p2pRoleRef, matchInfoRef,
  }
}
