{"content": "import { describe, it, expect } from 'vitest'
import { computeHash, updateHash } from './ai.js'

describe('computeHash', () => {
  it('returns [0,0] for empty board', () => {
    const board = Array.from({ length: 15 }, () => Array(15).fill(0))
    expect(computeHash(board)).toEqual([0, 0])
  })

  it('returns non-zero for non-empty board', () => {
    const board = Array.from({ length: 15 }, () => Array(15).fill(0))
    board[7][7] = 1
    const hash = computeHash(board)
    expect(hash[0] !== 0 || hash[1] !== 0).toBe(true)
  })

  it('is deterministic', () => {
    const board = Array.from({ length: 15 }, () => Array(15).fill(0))
    board[7][7] = 1; board[7][8] = 2
    expect(computeHash(board)).toEqual(computeHash(board))
  })
})

describe('updateHash', () => {
  it('returns new array (no mutation)', () => {
    const hash = [123, 456]
    const updated = updateHash(hash, 0, 0, 1)
    expect(updated).not.toBe(hash)
    expect(hash).toEqual([123, 456])
  })

  it('same position+player XORs back to original', () => {
    const hash = [100, 200]
    const updated = updateHash(hash, 5, 5, 1)
    const reverted = updateHash(updated, 5, 5, 1)
    expect(reverted).toEqual(hash)
  })

  it('different positions produce different hashes', () => {
    const h1 = updateHash([0, 0], 0, 0, 1)
    const h2 = updateHash([0, 0], 0, 1, 1)
    expect(h1[0] !== h2[0] || h1[1] !== h2[1]).toBe(true)
  })

  it('different players produce different hashes', () => {
    const h1 = updateHash([0, 0], 7, 7, 1)
    const h2 = updateHash([0, 0], 7, 7, 2)
    expect(h1[0] !== h2[0] || h1[1] !== h2[1]).toBe(true)
  })
})
